:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8a9a;
}
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Courier New', monospace;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}
.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  image-rendering: pixelated;
}
h1 {
  font-size: 24px;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 16px;
  color: var(--accent);
}
.stats {
  display: flex;
  gap: 24px;
  margin-bottom: 16px;
  font-size: 16px;
  color: var(--muted);
}
.stats strong {
  color: var(--text);
}
.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}
input[type="text"] {
  flex: 1;
  min-width: 0;
  background: var(--bg);
  border: 3px solid var(--muted);
  color: var(--text);
  font-family: inherit;
  font-size: 16px;
  padding: 10px 12px;
  outline: none;
}
input[type="text"]:focus {
  border-color: var(--accent);
}
button {
  background: var(--accent);
  color: var(--text);
  border: 3px solid var(--accent);
  font-family: inherit;
  font-size: 16px;
  font-weight: bold;
  padding: 10px 16px;
  cursor: pointer;
  text-transform: uppercase;
}
button:hover {
  background: #ff5c77;
  border-color: #ff5c77;
}
button:active {
  background: #c0304a;
  border-color: #c0304a;
  transform: translate(1px, 1px);
}
button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}
.task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.task-item {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--bg);
  border: 3px solid var(--muted);
  padding: 10px 12px;
}
.task-item.done .task-text {
  text-decoration: line-through;
  color: var(--muted);
}
.task-text {
  flex: 1;
  word-break: break-word;
}
.task-item input[type="checkbox"] {
  width: 22px;
  height: 22px;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}
.task-item input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}
.task-item button {
  padding: 6px 10px;
  font-size: 14px;
  flex-shrink: 0;
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .stats {
    gap: 16px;
    font-size: 15px;
  }
}

(function () {
  'use strict';

  var tasks = [];
  var nextId = 1;

  var input = document.getElementById('todo-input');
  var addBtn = document.getElementById('todo-add');
  var list = document.getElementById('todo-list');
  var totalEl = document.getElementById('todo-total');
  var remainingEl = document.getElementById('remaining');

  function updateCounts() {
    var total = tasks.length;
    var remaining = tasks.filter(function (t) { return !t.done; }).length;
    totalEl.textContent = String(total);
    remainingEl.textContent = String(remaining);
  }

  function render() {
    list.innerHTML = '';
    tasks.forEach(function (task) {
      var li = document.createElement('li');
      li.className = 'task-item' + (task.done ? ' done' : '');

      var check = document.createElement('input');
      check.type = 'checkbox';
      check.id = 'todo-check-' + task.id;
      check.checked = task.done;
      check.setAttribute('aria-label', 'Mark task ' + task.id + ' complete');
      check.addEventListener('change', function () {
        task.done = check.checked;
        li.classList.toggle('done', task.done);
        updateCounts();
      });

      var span = document.createElement('span');
      span.className = 'task-text';
      span.id = 'todo-text-' + task.id;
      span.textContent = task.text;

      var del = document.createElement('button');
      del.type = 'button';
      del.id = 'todo-delete-' + task.id;
      del.textContent = 'Delete';
      del.setAttribute('aria-label', 'Delete task ' + task.id);
      del.addEventListener('click', function () {
        tasks = tasks.filter(function (t) { return t.id !== task.id; });
        render();
        updateCounts();
      });

      li.appendChild(check);
      li.appendChild(span);
      li.appendChild(del);
      list.appendChild(li);
    });
  }

  function addTask() {
    var text = input.value.trim();
    if (!text) return;
    tasks.push({ id: nextId++, text: text, done: false });
    input.value = '';
    input.focus();
    render();
    updateCounts();
  }

  addBtn.addEventListener('click', addTask);
  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') addTask();
  });

  updateCounts();
})();
